#pragma once
static const char board_page[] = "<!doctype html><html lang=\"zh-CN\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>汤圆本机 MimiClaw</title><style>body{max-width:800px;margin:30px auto;padding:16px;background:#101827;color:#e8edf7;font:16px system-ui}button,input,textarea{font:inherit;margin:5px;padding:10px;max-width:100%;box-sizing:border-box}textarea{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere}button{cursor:pointer}</style><h1>汤圆本机 MimiClaw</h1><p>这页由机器人提供。Agent、工具和转头在机器人执行；大模型需要网络。语音识别、原音色和手势仍需电脑辅助。当前半双工，播放时请用安静按钮。</p><label>本机配对令牌 <input id=\"token\" type=\"password\" autocomplete=\"off\"></label><p><button onclick=\"go('/status')\">查看状态</button><button onclick=\"act('mute')\" style=\"background:#bd3649;color:white\">立即安静</button><button onclick=\"act('resume')\">恢复说话</button><button onclick=\"act('stop')\">停止动作和任务</button></p><p><button onclick=\"act('companion')\">陪伴模式</button><button onclick=\"act('follow')\">跟随</button><button onclick=\"act('follow_off')\">停止跟随</button><button onclick=\"act('gestures')\">开启手势</button><button onclick=\"act('gestures_off')\">关闭手势</button><button onclick=\"act('happy')\">开心</button></p><p><button onclick=\"act('left')\">向左一点</button><button onclick=\"act('right')\">向右一点</button><button onclick=\"act('up')\">抬头</button><button onclick=\"act('down')\">低头</button><button onclick=\"act('nod')\">点头</button><button onclick=\"act('shake')\">摇头</button></p><label>音量 <input id=\"volume\" type=\"range\" min=\"0\" max=\"100\" value=\"25\" onchange=\"go('/control',{action:'volume',value:Number(this.value)})\"></label><p><textarea id=\"task\" rows=\"5\" placeholder=\"例如：帮我检索两篇轻量手势识别论文，核对 DOI，保存报告并回读\"></textarea><button onclick=\"go('/task',{task:document.getElementById('task').value})\">执行工具任务</button></p><pre id=\"result\"></pre><script>function act(action){return go('/control',{action})}async function go(path,body){try{let r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+document.getElementById('token').value,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});let v=await r.json();document.getElementById('result').textContent=JSON.stringify(v,null,2)}catch{document.getElementById('result').textContent='连接失败，请检查同一网络与机器人供电'}}</script></html>";
